  let dollars = 0
  let tokens = ZERO_TOKENS
  let unpriced = 0
  for (const r of [...turn.responses, ...turn.subagent]) {
    dollars += r.dollars
    tokens = addTokens(tokens, r.tokens)
    if (r.unpriced) unpriced++
  }
  return { dollars, tokens, unpriced }
